import { NavLink, useNavigate } from "react-router-dom";

const navItems = [
  { to: "/", label: "Home", end: true },
  { to: "/about", label: "About" },
  { to: "/services", label: "Services" },
  { to: "/contact", label: "Contact" },
  { to: "/careers", label: "Careers" },
];

function AdminDashboard({ setIsAuth }) {
  const navigate = useNavigate();

  const handleLogout = () => {
    localStorage.removeItem("adminAuth");
    setIsAuth(false);
    navigate("/admin");
  };

  return (
    <div className="min-vh-100 d-flex" style={{ background: "#f4f6f9" }}>
      <aside
        className="bg-white border-end d-flex flex-column"
        style={{ width: 260, minHeight: "100vh", boxShadow: "1px 0 0 #e9ecef" }}
      >
        <div className="p-4 border-bottom">
          <div className="fw-bold fs-5 text-dark">DESAM Admin</div>
          <div className="small text-muted mt-1">Frontend-only preview</div>
        </div>
        <nav className="nav flex-column p-3 gap-1 flex-grow-1">
          {navItems.map(({ to, label, end }) => (
            <NavLink
              key={to}
              to={to}
              end={end}
              className={({ isActive }) =>
                `nav-link rounded px-3 py-2 ${isActive ? "active bg-primary text-white" : "text-body"}`
              }
            >
              {label}
            </NavLink>
          ))}
        </nav>
        <div className="p-3 border-top">
          <button type="button" className="btn btn-outline-danger w-100" onClick={handleLogout}>
            Log out
          </button>
        </div>
      </aside>

      <main className="flex-grow-1 p-4 p-lg-5 overflow-auto">
        <h1 className="h3 mb-3">Dashboard</h1>
        <p className="text-secondary mb-4" style={{ maxWidth: 560 }}>
          Open any section from the sidebar to view the public site. While you are signed in, inline
          editing controls stay available on pages that support them. Changes are stored in this
          browser only until you connect an API again.
        </p>
        <div className="row g-3">
          {navItems.map(({ to, label }) => (
            <div key={to} className="col-sm-6 col-lg-4">
              <NavLink
                to={to}
                end={to === "/"}
                className="d-block p-4 bg-white rounded border text-decoration-none text-dark h-100 shadow-sm"
              >
                <span className="fw-semibold">{label}</span>
                <div className="small text-muted mt-2">Go to page →</div>
              </NavLink>
            </div>
          ))}
        </div>
      </main>
    </div>
  );
}

export default AdminDashboard;
